const LOGO_SRC = "data:image/png;base64,";

import { CSSProperties } from 'react';

interface LogoProps {
  size?: 'sm' | 'md' | 'lg' | 'custom';
  className?: string;
  style?: CSSProperties;
}

export const Logo = ({ size = 'md', className = '', style = {} }: LogoProps) => {
  const widths = { sm: 80, md: 140, lg: 240, custom: 140 };
  const widthKey = size as 'sm' | 'md' | 'lg' | 'custom';
  return (
    <img
      src={LOGO_SRC}
      alt="Share idea"
      width={widths[widthKey] || widths.md}
      style={{ display: 'block', objectFit: 'contain', ...style }}
      className={className}
    />
  );
};

export default Logo;
